import { ok, fail } from './result.js';
import { roundCents } from './money.js';
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { isValidDate, addDays } from './dates.js';

/**
 * Calculate the due date based on payment terms and issue date.
 * @param {string} issueDate Date in YYYY-MM-DD format
 * @param {string} terms 'NET14', 'NET30', or 'EOM'
 * @returns {string} Due date in YYYY-MM-DD format
 */
function calculateDueDate(issueDate, terms) {
  if (terms === 'NET14') {
    return addDays(issueDate, 14);
  } else if (terms === 'NET30') {
    return addDays(issueDate, 30);
  } else if (terms === 'EOM') {
    // Last day of the issue date's month
    const [year, month] = issueDate.split('-');
    const lastDay = new Date(Number(year), Number(month), 0).getDate();
    return `${year}-${month}-${String(lastDay).padStart(2, '0')}`;
  }
  return null;
}

/**
 * Create a draft invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }>, terms?: string }} input
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, terms: string, dueDate: string, status: 'draft', lines: Array } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines, terms = 'NET30' }) {
  // Normalize customer ID
  const normalizedCustomerId = normalizeId(customerId);

  // Validate customer exists
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;
  const customer = customerResult.value;

  // Validate issueDate format (YYYY-MM-DD)
  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  // Validate and process payment terms
  if (!['NET14', 'NET30', 'EOM'].includes(terms)) {
    return fail('TERMS_INVALID');
  }
  const dueDate = calculateDueDate(issueDate, terms);

  // Validate lines is not empty
  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  // Validate and enrich each line
  const enrichedLines = [];
  for (const line of lines) {
    // Validate qty
    if (!Number.isInteger(line.qty) || line.qty <= 0) {
      return fail('QTY_INVALID');
    }

    // Validate discountPercent
    if (line.discountPercent != null) {
      if (typeof line.discountPercent !== 'number' || isNaN(line.discountPercent) || line.discountPercent < 0 || line.discountPercent > 100) {
        return fail('DISCOUNT_INVALID');
      }
    }

    // Validate SKU exists and get product details
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;

    // Apply tier discount if no explicit discount provided
    const lineDiscountPercent = line.discountPercent ?? TIER_DISCOUNTS[customer.tier];

    enrichedLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent: lineDiscountPercent,
    });
  }

  return ok({
    customerId: normalizedCustomerId,
    issueDate,
    terms,
    dueDate,
    status: 'draft',
    lines: enrichedLines,
  });
}

/**
 * Calculate the total for a single line (qty × unitPrice).
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {{ ok: true, value: number } | { ok: false, error: string }}
 */
export function lineTotal(line) {
  if (!line || line.qty == null || line.unitPrice == null) {
    return fail('INVALID_LINE');
  }
  return ok(line.qty * line.unitPrice);
}

/**
 * Calculate totals for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate?: number }>, voucher?: { amount: number } }} invoice
 * @returns {{ ok: true, value: { subtotal: number, discount: number, vat: number, voucher: number, total: number } } | { ok: false, error: string }}
 */
export function invoiceTotals(invoice) {
  if (!invoice || !Array.isArray(invoice.lines) || invoice.lines.length === 0) {
    return fail('INVALID_INVOICE');
  }

  let subtotal = 0;
  let discount = 0;
  let vat = 0;

  for (const line of invoice.lines) {
    const result = lineTotal(line);
    if (!result.ok) return result;
    const lineTotalAmount = result.value;
    subtotal += lineTotalAmount;

    // Calculate line discount
    const discountFractional = lineTotalAmount * (line.discountPercent ?? 0) / 100;
    const lineDiscount = roundCents(discountFractional);
    discount += lineDiscount;

    // Calculate line VAT (on amount after discount)
    const amountAfterDiscount = lineTotalAmount - lineDiscount;
    const vatFractional = amountAfterDiscount * (line.vatRate ?? 0) / 100;
    const lineVat = roundCents(vatFractional);
    vat += lineVat;
  }

  const voucher = invoice.voucher?.amount ?? 0;

  // Clamp total at 0
  const total = Math.max(0, subtotal - discount + vat - voucher);

  return ok({ subtotal, discount, vat, voucher, total });
}

/**
 * Add or increase a line on a draft invoice.
 * @param {{ status: string, lines: Array<{ sku: string, qty: number }> }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} input
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  // Check invoice exists and is draft
  if (!invoice || invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  // Validate qty
  if (!Number.isInteger(qty) || qty <= 0) {
    return fail('QTY_INVALID');
  }

  // Validate discountPercent
  if (discountPercent != null) {
    if (typeof discountPercent !== 'number' || isNaN(discountPercent) || discountPercent < 0 || discountPercent > 100) {
      return fail('DISCOUNT_INVALID');
    }
  }

  // Validate SKU exists
  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const product = productResult.value;

  // Check if line already exists
  const existingLineIndex = invoice.lines.findIndex((l) => l.sku === sku);

  if (existingLineIndex !== -1) {
    // Update existing line's qty, keep existing discountPercent
    const newLines = invoice.lines.map((line, i) =>
      i === existingLineIndex ? { ...line, qty: line.qty + qty } : line
    );
    return ok({ ...invoice, lines: newLines });
  } else {
    // For new lines, apply tier discount if no explicit discount provided
    let lineDiscountPercent = discountPercent;
    if (lineDiscountPercent === undefined) {
      const customerResult = getCustomer(invoice.customerId);
      if (!customerResult.ok) return customerResult;
      lineDiscountPercent = TIER_DISCOUNTS[customerResult.value.tier];
    }

    const newLine = {
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent: lineDiscountPercent,
    };
    return ok({ ...invoice, lines: [...invoice.lines, newLine] });
  }
}

/**
 * Remove a line from a draft invoice.
 * @param {{ status: string, lines: Array<{ sku: string }> }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  // Check invoice exists and is draft
  if (!invoice || invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  // Find the line
  const lineIndex = invoice.lines.findIndex((l) => l.sku === sku);
  if (lineIndex === -1) {
    return fail('LINE_NOT_FOUND');
  }

  // Check if it's the last line
  if (invoice.lines.length === 1) {
    return fail('NO_LINES');
  }

  // Remove the line
  const newLines = invoice.lines.filter((_, i) => i !== lineIndex);
  return ok({ ...invoice, lines: newLines });
}

/**
 * Issue a draft invoice (assign number and change status to 'issued').
 * @param {{ status: string, issueDate: string }} invoice
 * @param {Array<string>} existingNumbers - Invoice numbers already in use
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  // Check invoice exists and is draft
  if (!invoice || invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  // Get the next invoice number
  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  // Return new invoice with number and status 'issued'
  return ok({ ...invoice, number, status: 'issued' });
}

