test('invoiceTotals on a real invoice from createInvoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  assert.equal(invoiceResult.ok, true);
  const totalsResult = invoiceTotals(invoiceResult.value);
  assert.equal(totalsResult.ok, true);
  const subtotal = 5 * 9500 + 1 * 120000; // 167500 cents
  const discount = Math.round(subtotal * 5 / 100); // 5% gold tier = 8375 cents
  const amountAfterDiscount = subtotal - discount; // 159125 cents
  const line1Vat = Math.round(45125 * 21 / 100); // 5*9500=47500, after 5% discount=45125, VAT 21%=9476.25≈9476
  const line2Vat = Math.round(114000 * 21 / 100); // 1*120000=120000, after 5% discount=114000, VAT 21%=23940
  const vat = line1Vat + line2Vat;
  const total = amountAfterDiscount + vat;
  assert.equal(totalsResult.value.subtotal, subtotal);
  assert.equal(totalsResult.value.discount, discount);
  assert.equal(totalsResult.value.vat, vat);
  assert.equal(totalsResult.value.total, total);
});

