test('invoiceTotals calculates VAT per line on amount after discount', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  });
  assert.equal(invoiceResult.ok, true);

  const r = invoiceTotals(invoiceResult.value);
  assert.equal(r.ok, true);
  const lineTotal = 10 * 9500; // 95000 cents
  const discount = Math.round(lineTotal * 10 / 100); // 9500 cents
  const amountAfterDiscount = lineTotal - discount; // 85500 cents
  const expectedVat = Math.round(amountAfterDiscount * 21 / 100); // 17955 cents
  assert.equal(r.value.vat, expectedVat);
});

